// Import the shared database client (Prisma)
import { prisma } from "../../lib/prisma.js";
// Import the TypeScript types of our enums (generated by Prisma from schema.prisma)
import type { Role, TicketPriority, TicketStatus } from "../../generated/prisma/enums.js";

// THE STATE MACHINE: for each current status, the list of statuses it may move to
// "Record<TicketStatus, TicketStatus[]>" means: one entry per status, each holding an array of statuses
export const ALLOWED_TRANSITIONS: Record<TicketStatus, TicketStatus[]> = {
  // A new ticket can only be picked up
  OPEN: ["IN_PROGRESS"],
  // Work in progress can be finished, or put back in the queue
  IN_PROGRESS: ["OPEN", "RESOLVED"],
  // A resolved ticket can be closed for good, or reopened if the fix did not work
  RESOLVED: ["OPEN", "CLOSED"],
  // CLOSED is final; if the customer returns, a NEW ticket is created (keeps history and reports clean)
  CLOSED: [],
};

// The ways an action can fail, so the controller can turn each into the right HTTP status code
type Failure = {
  // ok: false lets TypeScript tell a failure apart from a success (a "discriminated union")
  ok: false;
  // A short machine-readable reason
  reason: "NOT_FOUND" | "FORBIDDEN" | "INVALID_TRANSITION" | "CONFLICT" | "ASSIGNEE_NOT_MEMBER" | "TICKET_CLOSED";
  // For INVALID_TRANSITION: which moves WERE allowed (helpful for the client)
  allowed?: TicketStatus[];
};

// The columns we show in ticket lists and summaries (pick only what we need; never return everything)
const ticketSummarySelect = {
  // Ticket identity and details
  id: true,
  subject: true,
  status: true,
  priority: true,
  createdAt: true,
  updatedAt: true,
  // The customer who raised it
  customer: { select: { id: true, name: true, email: true } },
  // The staff member it is assigned to (assignedTo is a Membership, so we hop to its user)
  assignedTo: { select: { user: { select: { id: true, name: true } } } },
} as const;

// Turn a database row into a clean API shape (flatten assignedTo -> assignee, and say which status moves are allowed next)
function shapeTicket<T extends { status: TicketStatus; assignedTo: { user: { id: string; name: string } } | null }>(ticket: T) {
  // Separate assignedTo from the rest of the fields
  const { assignedTo, ...rest } = ticket;
  // Return everything else plus a friendlier "assignee" field (null when nobody is assigned)
  // and "allowedNext": the state machine's answer, so a frontend never has to copy the rules (one source of truth)
  return { ...rest, assignee: assignedTo ? assignedTo.user : null, allowedNext: ALLOWED_TRANSITIONS[ticket.status] };
}

// Create a ticket, finding or creating the customer by email, all in ONE transaction
export async function createTicket(
  // The business the ticket belongs to
  orgId: string,
  // The validated request data
  input: { customer: { name: string; email: string }; subject: string; description: string; priority: TicketPriority },
) {
  // A transaction = several database steps that succeed or fail TOGETHER (no half-created data)
  return prisma.$transaction(async (tx) => {
    // upsert = "update or insert": find the customer by (business, email), or create them if they are new
    const customer = await tx.customer.upsert({
      // organizationId_email is the name Prisma gives the @@unique([organizationId, email]) pair
      where: { organizationId_email: { organizationId: orgId, email: input.customer.email } },
      // If not found, create the customer inside THIS business only
      create: { organizationId: orgId, email: input.customer.email, name: input.customer.name },
      // If found, change nothing (we do not let a new ticket overwrite the stored customer name)
      update: {},
    });

    // Create the ticket linked to that customer; this link is what builds the customer's history
    const ticket = await tx.ticket.create({
      // The data of the new row (status starts as OPEN by default in the schema)
      data: {
        // Tenant ownership: this ticket belongs to this business
        organizationId: orgId,
        // Link to the customer found or created above
        customerId: customer.id,
        // The title
        subject: input.subject,
        // The details
        description: input.description,
        // The urgency
        priority: input.priority,
      },
      // Return the summary columns
      select: ticketSummarySelect,
    });

    // Return the clean shape
    return shapeTicket(ticket);
  });
}

// List tickets of one business with optional filters and page-number pagination
export async function listTickets(
  // The business whose tickets we list
  orgId: string,
  // The id of the logged-in user (needed for the "assigned to me" filter)
  userId: string,
  // The validated query (filters + page + limit)
  // (each optional filter says "| undefined" explicitly because our tsconfig uses exactOptionalPropertyTypes)
  query: { status?: TicketStatus | undefined; priority?: TicketPriority | undefined; assignedTo?: "me" | "unassigned" | undefined; page: number; limit: number },
) {
  // Build the WHERE condition; organizationId is ALWAYS present (the tenant filter)
  const where = {
    // TENANT FILTER: never list tickets of another business
    organizationId: orgId,
    // Add the status filter only if the client sent one (the ... spread of {} adds nothing)
    ...(query.status ? { status: query.status } : {}),
    // Add the priority filter only if sent
    ...(query.priority ? { priority: query.priority } : {}),
    // "unassigned" = tickets with no assignee yet
    ...(query.assignedTo === "unassigned" ? { assignedToId: null } : {}),
    // "me" = tickets whose assigned membership belongs to the logged-in user
    ...(query.assignedTo === "me" ? { assignedTo: { is: { userId } } } : {}),
  };

  // Run the page query and the total count together, in one round trip
  const [rows, total] = await prisma.$transaction([
    // The page of tickets, newest first
    prisma.ticket.findMany({
      // The filters from above
      where,
      // The columns to return
      select: ticketSummarySelect,
      // Newest tickets first
      orderBy: { createdAt: "desc" },
      // Skip the rows of earlier pages (page 1 skips 0, page 2 skips "limit", ...)
      skip: (query.page - 1) * query.limit,
      // Take at most "limit" rows
      take: query.limit,
    }),
    // The total number of matching tickets (so the client can show "page 2 of 7")
    prisma.ticket.count({ where }),
  ]);

  // Return the page plus paging information
  return { items: rows.map(shapeTicket), page: query.page, limit: query.limit, total };
}

// Fetch ONE ticket with its customer and full conversation; null if it is not in this business
export async function getTicket(orgId: string, ticketId: string) {
  // findFirst (not findUnique) because we filter by TWO fields: the ticket id AND the business
  const ticket = await prisma.ticket.findFirst({
    // TENANT FILTER: a ticket id from another business simply will not match
    where: { id: ticketId, organizationId: orgId },
    // Choose the columns
    select: {
      // The same summary columns as the list
      ...ticketSummarySelect,
      // The full description is only needed on the detail view
      description: true,
      // The conversation, oldest message first
      messages: {
        // Order messages chronologically
        orderBy: { createdAt: "asc" },
        // Message columns plus who wrote it
        select: {
          id: true,
          body: true,
          createdAt: true,
          senderType: true,
          sender: { select: { id: true, name: true } },
          customer: { select: { id: true, name: true } },
        },
      },
    },
  });
  // Not found (or belongs to another business): the caller answers 404
  if (!ticket) return null;
  // Return the clean shape
  return {
    ...shapeTicket(ticket),
    messages: ticket.messages.map(({ senderType, sender, customer, ...message }) => ({
      ...message,
      sender:
        senderType === "STAFF"
          ? { id: sender?.id ?? null, name: sender?.name ?? "Former staff member", type: senderType }
          : { id: customer?.id ?? null, name: customer?.name ?? "Customer", type: senderType },
    })),
  };
}

// Move a ticket to a new status, following the state machine and role rules
export async function changeTicketStatus(orgId: string, ticketId: string, newStatus: TicketStatus, role: Role) {
  // Load the ticket, but only if it belongs to this business
  const ticket = await prisma.ticket.findFirst({
    // TENANT FILTER
    where: { id: ticketId, organizationId: orgId },
    // We only need the current status here
    select: { status: true },
  });
  // Not found or belongs to another business
  if (!ticket) return { ok: false, reason: "NOT_FOUND" } satisfies Failure;

  // Business rule: only OWNER and ADMIN may close a ticket for good (AGENTs can resolve, not close)
  if (newStatus === "CLOSED" && role === "AGENT") return { ok: false, reason: "FORBIDDEN" } satisfies Failure;

  // Look up which moves are allowed from the CURRENT status
  const allowed = ALLOWED_TRANSITIONS[ticket.status];
  // If the requested move is not in the list, refuse and tell the client what is allowed
  if (!allowed.includes(newStatus)) return { ok: false, reason: "INVALID_TRANSITION", allowed } satisfies Failure;

  // "Compare-and-swap": update ONLY IF the status is still what we just read (protects against two agents acting at the same moment)
  const result = await prisma.ticket.updateMany({
    // Match the ticket, the business, AND the status we saw
    where: { id: ticketId, organizationId: orgId, status: ticket.status },
    // The change itself
    data: { status: newStatus },
  });
  // count 0 means someone else changed the ticket between our read and our write
  if (result.count === 0) return { ok: false, reason: "CONFLICT" } satisfies Failure;

  // Success: fetch the fresh ticket summary to return
  const updated = await prisma.ticket.findFirstOrThrow({
    // Same tenant-safe lookup
    where: { id: ticketId, organizationId: orgId },
    // The summary columns
    select: ticketSummarySelect,
  });
  // Return success with the clean shape
  return { ok: true, ticket: shapeTicket(updated) } as const;
}

// Assign a ticket to a team member (or unassign it with null)
export async function assignTicket(orgId: string, ticketId: string, userId: string | null) {
  // Load the ticket, but only if it belongs to this business
  const ticket = await prisma.ticket.findFirst({
    // TENANT FILTER
    where: { id: ticketId, organizationId: orgId },
    // We need the status to block changes on closed tickets
    select: { status: true },
  });
  // Not found or belongs to another business
  if (!ticket) return { ok: false, reason: "NOT_FOUND" } satisfies Failure;
  // A closed ticket is final, so it cannot be reassigned
  if (ticket.status === "CLOSED") return { ok: false, reason: "TICKET_CLOSED" } satisfies Failure;

  // By default we unassign (null); this changes below if a user was given
  let membershipId: string | null = null;
  // If a user was given, they must be a member of THIS business (never assign to an outsider)
  if (userId) {
    // Look for the membership linking that user to this business
    const membership = await prisma.membership.findUnique({
      // The composite unique key (userId + organizationId)
      where: { userId_organizationId: { userId, organizationId: orgId } },
    });
    // Not a member of this business
    if (!membership) return { ok: false, reason: "ASSIGNEE_NOT_MEMBER" } satisfies Failure;
    // Tickets point to a Membership (not a User), so we store the membership id
    membershipId = membership.id;
  }

  // Save the assignment, again filtering by business as a second line of defense
  await prisma.ticket.updateMany({
    // Match the ticket inside this business
    where: { id: ticketId, organizationId: orgId },
    // The change itself
    data: { assignedToId: membershipId },
  });

  // Fetch the fresh ticket summary to return
  const updated = await prisma.ticket.findFirstOrThrow({
    // Same tenant-safe lookup
    where: { id: ticketId, organizationId: orgId },
    // The summary columns
    select: ticketSummarySelect,
  });
  // Return success with the clean shape
  return { ok: true, ticket: shapeTicket(updated) } as const;
}

// Add a staff reply to a ticket's conversation
export async function addMessage(orgId: string, ticketId: string, senderId: string, body: string) {
  // Load the ticket, but only if it belongs to this business
  const ticket = await prisma.ticket.findFirst({
    // TENANT FILTER
    where: { id: ticketId, organizationId: orgId },
    // We need the status to block replies on closed tickets
    select: { status: true },
  });
  // Not found or belongs to another business
  if (!ticket) return { ok: false, reason: "NOT_FOUND" } satisfies Failure;
  // No new messages on a closed ticket (the customer should open a new one)
  if (ticket.status === "CLOSED") return { ok: false, reason: "TICKET_CLOSED" } satisfies Failure;

  // Create the message and bump the ticket's updatedAt together, so "recent activity" sorting stays correct
  const [message] = await prisma.$transaction([
    // The new message
    prisma.message.create({
      // Link it to the ticket and to the staff member who wrote it
      data: { ticketId, senderId, senderType: "STAFF", body },
      // Return the message columns plus the sender's name
      select: {
        id: true,
        body: true,
        createdAt: true,
        senderType: true,
        sender: { select: { id: true, name: true } },
      },
    }),
    // Touch the ticket so its updatedAt changes (filtered by business, as always)
    prisma.ticket.updateMany({ where: { id: ticketId, organizationId: orgId }, data: { updatedAt: new Date() } }),
  ]);
  const { senderType, sender, ...messageData } = message;
  return {
    ok: true,
    message: {
      ...messageData,
      sender: { id: sender?.id ?? null, name: sender?.name ?? "Former staff member", type: senderType },
    },
  } as const;
}
